package com.gymmind.nutrition.domain.model;
import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*;
@Entity @Table(name="nutrition_plan") public class NutritionPlan extends TenantScopedEntity { @Column(name="member_id",nullable=false) Long memberId; @Column(nullable=false) double caloriesTarget; @Column(nullable=false) double proteinTarget; @Column(nullable=false) double carbohydrateTarget; @Column(nullable=false) double fatTarget; @Column(nullable=false,length=2000) String description; protected NutritionPlan(){} private NutritionPlan(Long t,Long m,double c,double p,double carb,double f,String d){super(t);if(m==null||m<=0||c<0||p<0||carb<0||f<0||d==null||d.isBlank())throw new IllegalArgumentException("Invalid nutrition plan");memberId=m;caloriesTarget=c;proteinTarget=p;carbohydrateTarget=carb;fatTarget=f;description=d.trim();} public static NutritionPlan create(Long t,Long m,double c,double p,double carb,double f,String d){return new NutritionPlan(t,m,c,p,carb,f,d);} public Long getMemberId(){return memberId;} public double getCaloriesTarget(){return caloriesTarget;} public double getProteinTarget(){return proteinTarget;} public double getCarbohydrateTarget(){return carbohydrateTarget;} public double getFatTarget(){return fatTarget;} public String getDescription(){return description;} }
